arguments.command:
node -e '
const fs = require("fs");
const text = fs.readFileSync("README.md", "utf8");

const cloneMatch = text.match(/https:\/\/github\.com\/Indosaram\/ferryx\.git/g);
const pagesMatch = text.match(/https:\/\/indosaram\.github\.io\/ferryx\//g);

console.log("Clone URL found:", cloneMatch ? cloneMatch.length : 0);
console.log("Pages URL found:", pagesMatch ? pagesMatch.length : 0);

if (!cloneMatch || !pagesMatch) {
  process.exit(1);
}
'
